import{z as p,x as A,o as r,c as d,q as t,j as o,D as n,d as e,s,S as i,b as l}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"NEFTune","description":"","frontmatter":{"title":"NEFTune","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/neftune.md","filePath":"llm/neftune.md","lastUpdated":1791063341000}'),m={name:"llm/neftune.md"};function B(h,a,u,f,T,C){const E=A("Mermaid");return r(),d("div",null,[a[2]||(a[2]=t('<h1 id="neftune" tabindex="-1">NEFTune <a class="header-anchor" href="#neftune" aria-label="Permalink to &quot;NEFTune&quot;">​</a></h1><div class="epigraph"><p>指令集又短又容易背；在嵌入上加一点与长度、维度成比例的噪声，完成质量可以涨，而无需改损失或换表。</p><footer>—— Jain 等，NEFTune: Noisy Embeddings Improve Instruction Finetuning，ICLR 2024</footer></div><p><a href="/llm/sft-packing-mask">打包与掩码</a>把短指令的硬件浪费收掉之后，剩下的病是<strong>背诵</strong>：<a href="/llm/instruction-data-lineage">谱系</a>里无论 FLAN 网格还是 Alpaca 5 万条，相对预训练都极小，全参或 <a href="/llm/lora">LoRA</a> 都能把示范 n-gram 写入权重。<a href="/llm/response-only-loss">仅回复损失</a>只决定背的是回答而不是问题，不阻止背。Jain、Chiang、Wen 等人的 NEFTune 在训练时对输入嵌入加均匀噪声，推理不加。本课写这一种正则，不谈学习率分叉（<a href="/llm/lora-vs-full-lr">下一课</a>）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SFT 过拟合的表面是训练回复 NLL 下降、开放生成变刻板：固定开头、固定列表、固定客套。Dropout 在残差流上对指令这种短序列往往过猛或不够；权重衰减与预训练范数打架，<a href="/llm/full-sft-hparams">全参配方</a>已经建议减弱它。需要一种专门针对「嵌入空间里的精确记忆」的扰动：同一条指令每次前向看到的是附近的点，而不是同一向量序列。</p><p>噪声太大，条件被毁，模型学不会<a href="/llm/chat-template">模板</a>边界；太小，等于没加。尺度必须随序列长度与嵌入维变化，否则 512 维与 4096 维、短指令与打包长包不能共用一个 \\(\\alpha\\)。</p><h3 id="噪声加在嵌入-不加在权重" tabindex="-1">噪声加在嵌入，不加在权重 <a class="header-anchor" href="#噪声加在嵌入-不加在权重" aria-label="Permalink to &quot;噪声加在嵌入，不加在权重&quot;">​</a></h3><p>在 \\(W\\) 上加噪接近权重衰减的表亲；在激活深处加噪干扰已对齐的特征。NEFTune 选择词嵌入输出：token 身份仍在（离散 id 未变），连续表示被推离训练集上的精确点。这与对抗训练不同：没有攻击者、没有内循环，只是均匀块噪声。</p><p><span class="marginnote">论文在 LLaMA 与若干指令集上报告对话评分上升，并强调推理时噪声为零，部署与基座相同。它不是数据增强生成新指令，而是同一样本的嵌入抖动。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设嵌入矩阵查出的向量为 \\(X\\in\\mathbb{R}^{B\\times C\\times d}\\)（\\(C\\) 为序列长度）。训练时</p> \\[X\\leftarrow X+\\frac{\\alpha}{\\sqrt{Cd}}\\,\\epsilon,\\qquad \\epsilon\\sim\\mathrm{Unif}(-1,1). \\]<p>\\(\\alpha\\) 是唯一主超参，原文常用 5 量级，需按模型宽度重扫。噪声在 embedding 之后、进入第一层 Transformer 之前注入；<a href="/llm/response-only-loss">仅回复</a>的 labels 不变——抖动的是条件与目标共享的表示，不是改哪些位置计损失。推理与评测关掉噪声，否则与训练分布又错位一层。</p><p><span class="marginnote">尺度代个数字：\\(C=512\\)、\\(d=4096\\) 时 \\(\\sqrt{Cd}\\approx1448\\)，\\(\\alpha=5\\) 意味着每维扰动幅度约 \\(5/1448\\approx0.003\\)——相对嵌入向量的典型量级是「轻轻推一把」。而 \\(d=512\\) 的小模型上同样 \\(\\alpha=5\\) 幅度大约翻 2.8 倍，这就是「换宽度要重扫 \\(\\alpha\\)」的算术来源。</span></p><p>与打包兼容：公式里的 \\(C\\) 应是<strong>本序列有效长度</strong>还是窗口 \\(L\\)，要固定一种。用窗口 \\(L\\) 则短包噪声偏小；用有效长度则不同包尺度不同。实现应写死，并在打开 packing 后重扫 \\(\\alpha\\)。</p>',15)),(r(),o(i,null,{default:n(()=>[s(E,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20Tok%5B%22token%20id%22%5D%20--%3E%20Emb%5B%22%E8%AF%8D%E5%B5%8C%E5%85%A5%22%5D%0A%20%20Emb%20--%3E%20N%5B%22%E5%8A%A0%E5%9D%87%E5%8C%80%E5%99%AA%E5%A3%B0%20%CE%B1%2Fsqrt(C%20d)%22%5D%0A%20%20N%20--%3E%20T%5B%22Transformer%22%5D%0A%20%20T%20--%3E%20L%5B%22%E4%BB%85%E5%9B%9E%E5%A4%8D%E6%8D%9F%E5%A4%B1%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("p",null,[e("NEFTune 不替代配比与过滤。脏 ShareGPT 加噪声，只是把背诵变成背嘈杂版；干净千条（"),l("a",{href:"/llm/lima"},"LIMA"),e("）上它才更像正则而不是遮丑。")],-1)),a[4]||(a[4]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=l("p",null,[e("嵌入噪声使同一指令的前缀表示在球面上小幅游走。注意力看到的键值不再能用「精确匹配训练集前缀」检索出背好的续写，被迫使用更粗的指令语义。这与 dropout 随机切单元不同：所有维度仍在，只是平移。均匀分布各向同性，不偏向某类 token；特殊标记也会被推离，所以 \\(\\alpha\\) 过大时角色边界先坏——表现为"),l("a",{href:"/llm/chat-template"},"模板"),e("像坏了，其实是噪声淹没了分隔向量。")],-1)),(r(),o(i,null,{default:n(()=>[s(E,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%E6%8C%87%E4%BB%A4%20%E8%AE%AD%E7%BB%83%E7%AC%AC%20N%20%E9%81%8D%22%5D%20--%3E%20NO%5B%22%E6%97%A0%E5%99%AA%E5%A3%B0%3A%20%E5%B5%8C%E5%85%A5%E8%BF%98%E6%98%AF%E5%90%8C%E4%B8%80%E4%B8%AA%E7%82%B9%22%5D%0A%20%20NO%20--%3E%20MEM%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%E7%B2%BE%E7%A1%AE%E5%8C%B9%E9%85%8D%E5%89%8D%E7%BC%80%20%E2%86%92%20%E8%83%8C%E5%87%BA%E5%AD%98%E5%A5%BD%E7%9A%84%E7%BB%AD%E5%86%99%22%5D%0A%20%20INS%20--%3E%20W%5B%22%E6%9C%89%E5%99%AA%E5%A3%B0%3A%20%E5%89%8D%E7%BC%80%E8%A1%A8%E7%A4%BA%E5%B0%8F%E5%B9%85%E6%B8%B8%E8%B5%B0%22%5D%0A%20%20W%20--%3E%20SEM%5B%22%E7%B2%BE%E7%A1%AE%E5%8C%B9%E9%85%8D%E5%A4%B1%E6%95%88%20%E2%86%92%20%E5%8F%AA%E5%89%A9%E8%AF%AD%E4%B9%89%E6%A3%80%E7%B4%A2%22%5D%0A%20%20SEM%20--%3E%20GEN%5B%22%E8%A2%AB%E8%BF%AB%E6%B3%9B%E5%8C%96%20%E8%BE%93%E5%87%BA%E6%9B%B4%E5%A4%9A%E6%A0%B7%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">可以把它想象成「换着说法问同一个问题」的连续版：数据增强是离线生成新的文本变体，NEFTune 是在同一条指令的表示上每一步都换个附近的位置。方向一样——不让模型把「这道题的答案」记成单个固定地址。</span></p><p>对 <a href="/llm/lora">LoRA</a>，噪声在冻结基座的嵌入上（若嵌入未挂适配器）仍然有效：适配器看到的是抖动后的残差流。若 LoRA 也打在 embedding，噪声与低秩更新叠加，更要保守 \\(\\alpha\\)。</p><p><span class="marginnote">NEFTune 不声称改进事实正确性。评分上升可以来自更少的模板化空话。知识类基准不是它的主指标；主指标是开放生成的多样与人评。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>领域适配、继续预训练、满文档语言建模上，嵌入噪声可能伤害已经稀缺的术语精确匹配，本课不外推到那些设定。RL 与偏好阶段通常也不加：奖励模型对抖动前缀的分数会漂。多模态里视觉 token 的「嵌入」尺度与文本不同，不能抄 \\(\\sqrt{Cd}\\)。</p><p><span class="marginnote">常见误区：把 NEFTune 当数据清洗的替代品。它抑制的是「精确背诵」这条通路，不动数据内容——错误答案加了噪声，模型只是不再逐字背错，错的东西还在权重里。所以顺序永远是：先过滤数据，再谈正则。</span></p><p>\\(\\alpha\\) 与学习率耦合。大学习率已经在破坏特征时，再加噪声会加速崩溃。应先按<a href="/llm/lora-vs-full-lr">全参或 LoRA 的学习率</a>站稳，再打开 NEFTune。它是正则旋钮，不是数据谱系的替代。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NEFTune 在 SFT 训练时对词嵌入加均匀噪声，推理关闭。</li><li>尺度为 \\(\\alpha/\\sqrt{Cd}\\)，使不同长度与宽度大致可比。</li><li>目标是减少对短指令集的精确背诵，改善开放完成。</li><li>过大 \\(\\alpha\\) 会淹没 chat 特殊 token，先表现为格式崩溃。</li><li>与 packing、LoRA 兼容，但 \\(C\\) 的定义与 \\(\\alpha\\) 需重扫。</li><li>出处：Jain 等，NEFTune，ICLR 2024。</li></ul>',9))])}const N=p(m,[["render",B]]);export{D as __pageData,N as default};
